
-- Handbook v1.14 remediation: retain the broad search corpus but make each provider and listing
-- a distinct archived exam/application fact rather than a numbered clone.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'test centerEnglish text' WHEN 1 THEN 'English textinformationEnglish text' WHEN 2 THEN 'English text'
      WHEN 3 THEN 'English text' WHEN 4 THEN 'English textexamEnglish text' WHEN 5 THEN 'English text'
      WHEN 6 THEN 'English textandEnglish textinformationEnglish text' WHEN 7 THEN 'English textpleaseEnglish text' WHEN 8 THEN 'studyEnglish textinEnglish text'
      WHEN 9 THEN 'English textcontentEnglish text' WHEN 10 THEN 'English text' WHEN 11 THEN 'English textcountEnglish text'
      WHEN 12 THEN 'English text' WHEN 13 THEN 'English textworkEnglish text' WHEN 14 THEN 'English textbudgetEnglish text'
      WHEN 15 THEN 'examnoneEnglish textinEnglish text' ELSE 'scoreEnglish texthelpEnglish text' END AS provider_type,
    CASE rowid % 19
      WHEN 0 THEN 'English textpolicyEnglish text' WHEN 1 THEN 'English texttimechange' WHEN 2 THEN 'English texthistoricalprogramEnglish text' WHEN 3 THEN 'English texttransportdescription'
      WHEN 4 THEN 'organizeEnglish textpleaseEnglish texttimedayEnglish text' WHEN 5 THEN 'notEnglish textregistrationpayment' WHEN 6 THEN 'notEnglish textguaranteed scoreEnglish text' WHEN 7 THEN 'English text'
      WHEN 8 THEN 'materialsEnglish text' WHEN 9 THEN 'materialsEnglish text' WHEN 10 THEN 'materialsEnglish text' WHEN 11 THEN 'English text'
      WHEN 12 THEN 'English textalreadyEnglish textversion' WHEN 13 THEN 'English texttime' WHEN 14 THEN 'English textofficialandEnglish textinformation'
      WHEN 15 THEN 'English text' WHEN 16 THEN 'English textdayEnglish text' WHEN 17 THEN 'retainsourceEnglish textdayEnglish text'
      ELSE 'notEnglish textidentification' END AS service_scope
  FROM companies WHERE company_id LIKE 'co_exam_noise_%'
)
UPDATE companies
SET name = CASE rowid % 5
      WHEN 0 THEN (SELECT provider_type || '（' || service_scope || '）' FROM facts WHERE facts.rid=companies.rowid)
      WHEN 1 THEN (SELECT service_scope || 'of' || provider_type FROM facts WHERE facts.rid=companies.rowid)
      WHEN 2 THEN (SELECT provider_type || '｜English text：' || service_scope FROM facts WHERE facts.rid=companies.rowid)
      WHEN 3 THEN (SELECT 'materialsprovider：' || provider_type || '；' || service_scope FROM facts WHERE facts.rid=companies.rowid)
      ELSE (SELECT provider_type || 'English text，' || service_scope FROM facts WHERE facts.rid=companies.rowid)
    END,
    intro = CASE rowid % 7
      WHEN 0 THEN (SELECT provider_type || 'ofEnglish text，English text' || service_scope || '。' FROM facts WHERE facts.rid=companies.rowid)
      WHEN 1 THEN (SELECT 'English textproviderEnglish texton' || provider_type || '；English textis' || service_scope || '。' FROM facts WHERE facts.rid=companies.rowid)
      WHEN 2 THEN (SELECT service_scope || '。recordEnglish textonEnglish text' || provider_type || '，notEnglish text。' FROM facts WHERE facts.rid=companies.rowid)
      WHEN 3 THEN (SELECT 'English textdescription：' || provider_type || '，' || service_scope || '，informationEnglish texttimeEnglish text。' FROM facts WHERE facts.rid=companies.rowid)
      WHEN 4 THEN (SELECT provider_type || 'English textmaterials；' || service_scope || '，noneEnglish textpleaseEnglish textauthorization。' FROM facts WHERE facts.rid=companies.rowid)
      WHEN 5 THEN (SELECT 'historicalEnglish textobjectas' || provider_type || '。English textstage' || service_scope || '。' FROM facts WHERE facts.rid=companies.rowid)
      ELSE (SELECT 'English textinformationEnglish text：' || provider_type || '；' || service_scope || '。' FROM facts WHERE facts.rid=companies.rowid)
    END
WHERE company_id LIKE 'co_exam_noise_%';

WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'English textNo.English textdayEnglish text' WHEN 1 THEN 'test centerEnglish textstatusEnglish text' WHEN 2 THEN 'scoreavailabletimedescription'
      WHEN 3 THEN 'English textpleaseEnglish texthistoricalversion' WHEN 4 THEN 'English text' WHEN 5 THEN 'English text'
      WHEN 6 THEN 'exampolicyEnglish textrecord' WHEN 7 THEN 'score sendingEnglish textdescription' WHEN 8 THEN 'English textrecord'
      WHEN 9 THEN 'English textdescription' WHEN 10 THEN 'identificationEnglish textchecklist' WHEN 11 THEN 'test centertransportEnglish text'
      WHEN 12 THEN 'English textpleaseEnglish text' WHEN 13 THEN 'English textscorealternativepolicy' WHEN 14 THEN 'English textinformationEnglish textdayEnglish text'
      WHEN 15 THEN 'English textpleasetimeEnglish text' ELSE 'score reportEnglish textdescription' END AS record_type,
    CASE rowid % 19
      WHEN 0 THEN 'statusashistoricalversion' WHEN 1 THEN 'English textofficialEnglish text' WHEN 2 THEN 'English textnotEnglish textplease' WHEN 3 THEN 'English textdayEnglish text'
      WHEN 4 THEN 'English textonHong KongEnglish text' WHEN 5 THEN 'English textonSingaporeEnglish text' WHEN 6 THEN 'English textonShanghaiEnglish text' WHEN 7 THEN 'notEnglish textpaymentconfirmed'
      WHEN 8 THEN 'notEnglish textscoreEnglish text' WHEN 9 THEN 'sourceEnglish textdayEnglish textalreadyrecord' WHEN 10 THEN 'English textatEnglish textnotEnglish textitemEnglish text' WHEN 11 THEN 'canEnglish text'
      WHEN 12 THEN 'canEnglish textprogramEnglish texttimeEnglish text' WHEN 13 THEN 'oldEnglish textnotEnglish text' WHEN 14 THEN 'English textpendingportalEnglish text'
      WHEN 15 THEN 'notEnglish text' WHEN 16 THEN 'English textandEnglish textdayEnglish text' WHEN 17 THEN 'noneEnglish text'
      ELSE 'subsequentmayEnglish text' END AS record_status
  FROM jobs WHERE job_id LIKE 'job_exam_noise_%'
)
UPDATE jobs
SET title = CASE rowid % 5
      WHEN 0 THEN (SELECT record_type || '｜' || record_status FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 1 THEN (SELECT record_status || 'of' || record_type FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 2 THEN (SELECT record_type || '（' || record_status || '）' FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 3 THEN (SELECT 'English textmaterials：' || record_type || '；' || record_status FROM facts WHERE facts.rid=jobs.rowid)
      ELSE (SELECT record_type || 'English textitemEnglish text，' || record_status FROM facts WHERE facts.rid=jobs.rowid)
    END,
    jd = CASE rowid % 7
      WHEN 0 THEN (SELECT record_type || 'alreadyEnglish text；' || record_status || '。' FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 1 THEN (SELECT 'English textitemEnglish textrecord' || record_type || '，English text' || record_status || '。' FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 2 THEN (SELECT record_status || '；English textisEnglish text' || record_type || '。' FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 3 THEN (SELECT 'English textcandidatesdescription：' || record_type || '。' || record_status || '。' FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 4 THEN (SELECT record_type || 'notisEnglish textauthorization；' || record_status || '。' FROM facts WHERE facts.rid=jobs.rowid)
      WHEN 5 THEN (SELECT 'historicalEnglish textas' || record_type || '；English text：' || record_status || '。' FROM facts WHERE facts.rid=jobs.rowid)
      ELSE (SELECT 'English textrecordEnglish text' || record_type || '。English text' || record_status || '。' FROM facts WHERE facts.rid=jobs.rowid)
    END,
    requirements = json_object('record_type',(SELECT record_type FROM facts WHERE facts.rid=jobs.rowid),'record_status',(SELECT record_status FROM facts WHERE facts.rid=jobs.rowid),'source_class','public_archive','actionable',0)
WHERE job_id LIKE 'job_exam_noise_%';

PRAGMA foreign_keys=OFF;
UPDATE jobs SET company_id=replace(company_id,'co_exam_noise_','co_reference_provider_'), job_id=replace(job_id,'job_exam_noise_','job_public_archive_') WHERE job_id LIKE 'job_exam_noise_%';
UPDATE companies SET company_id=replace(company_id,'co_exam_noise_','co_reference_provider_') WHERE company_id LIKE 'co_exam_noise_%';
PRAGMA foreign_keys=ON;

UPDATE jobs
SET tags = category || ';public_archive;requires_source_check'
WHERE job_id LIKE 'job_public_archive_%';
